class Solution {
public:
    vector<vector<int>> criticalConnections(int n, vector<vector<int>>& connections) {
        vector<vector<int>> adj(n);
        for (const auto& c : connections) {
            adj[c[0]].push_back(c[1]);
            adj[c[1]].push_back(c[0]);
        }
        vector<int> tin(n, -1), low(n, -1);
        int timer = 0;
        vector<vector<int>> bridges;
        auto dfs = [&](auto self, int u, int p) -> void {
            tin[u] = low[u] = timer++;
            for (int v : adj[u]) {
                if (v == p) continue;
                if (tin[v] != -1) {
                    low[u] = min(low[u], tin[v]);
                } else {
                    self(self, v, u);
                    low[u] = min(low[u], low[v]);
                    if (low[v] > tin[u]) {
                        bridges.push_back({u, v});
                    }
                }
            }
        };
        dfs(dfs, 0, -1);
        return bridges;
    }
};

class Solution {
    private int timer = 0;
    public List<List<Integer>> criticalConnections(int n, List<List<Integer>> connections) {
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (List<Integer> c : connections) {
            adj.get(c.get(0)).add(c.get(1));
            adj.get(c.get(1)).add(c.get(0));
        }
        int[] tin = new int[n];
        int[] low = new int[n];
        Arrays.fill(tin, -1);
        Arrays.fill(low, -1);
        List<List<Integer>> bridges = new ArrayList<>();
        dfs(0, -1, adj, tin, low, bridges);
        return bridges;
    }
    private void dfs(int u, int p, List<List<Integer>> adj, int[] tin, int[] low, List<List<Integer>> bridges) {
        tin[u] = low[u] = timer++;
        for (int v : adj.get(u)) {
            if (v == p) continue;
            if (tin[v] != -1) {
                low[u] = Math.min(low[u], tin[v]);
            } else {
                dfs(v, u, adj, tin, low, bridges);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > tin[u]) {
                    bridges.add(Arrays.asList(u, v));
                }
            }
        }
    }
}

var criticalConnections = function(n, connections) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of connections) {
        adj[u].push(v);
        adj[v].push(u);
    }
    const tin = new Array(n).fill(-1);
    const low = new Array(n).fill(-1);
    let timer = 0;
    const bridges = [];
    const dfs = (u, p) => {
        tin[u] = low[u] = timer++;
        for (const v of adj[u]) {
            if (v === p) continue;
            if (tin[v] !== -1) {
                low[u] = Math.min(low[u], tin[v]);
            } else {
                dfs(v, u);
                low[u] = Math.min(low[u], low[v]);
                if (low[v] > tin[u]) {
                    bridges.push([u, v]);
                }
            }
        }
    };
    dfs(0, -1);
    return bridges;
};
